        (N''000003343'', N''100402557'', N''Kura'', N''Doustnie, w wodzie do picia'', N''Leczenie inwazji ptasiego roztocza czerwonego (Dermanyssus gallinae) u kurek, kur hodowlanych i niosek.'', N''0,5 mg fluralaner/kg m.c. (=0,05 ml produktu/kg m.c.), podać dwukrotnie w odstępie 7 dni; pełny kurs jest konieczny. Wodę z lekiem podawać przez 4–24 godziny, bez innego źródła wody; kolejny kurs, jeśli potrzebny, najwcześniej po 3 miesiącach.'', N''data/ChPL/UPD/ema-combined-v4344-exzolt-vra0017-2024-08-20-pl.pdf'', N''Można stosować w okresie nieśności. Wodę z lekiem przygotować do spożycia w ciągu dnia leczenia; podczas podawania nie udostępniać innego źródła wody. Karencja jaj: 0 dni.'', N''tk. 14 dni, Jaja: 0 dni, Można stosować w okresie nieśności. Wodę z lekiem przygotować do spożycia w ciągu dnia leczenia; podczas podawania nie udostępniać innego źródła wody. Karencja jaj: 0 dni.'', N''tk. 14 dni, Jaja: 0 dni, Można stosować w okresie nieśności. Wodę z lekiem przygotować do spożycia w ciągu dnia leczenia; podczas podawania nie udostępniać innego źródła wody. Karencja jaj: 0 dni.'', N''0 dni''),
        (N''000000000000001066'', N''16599'', N''Kura'', N''W wodzie do picia lub przez zamgławianie (spray)'', N''Czynne uodparnianie kur przeciwko rzekomemu pomorowi ptaków (ND) i zakaźnemu zapaleniu oskrzeli ptaków (IB).'', N''1 dawka/ptaka wg programu szczepień stada (od 1. dnia życia).'', N''data/ChPL/RPL/RPL_16599_Bio-Vac_ND-IB_RPL_ChPL.pdf'', N''Do rozpuszczania używać czystej, chłodnej wody bez chloru i środków dezynfekcyjnych.'', N''tk. 0 dni, Jaja: 0 dni'', N''tk. 0 dni, Jaja: 0 dni'', N''0 dni''),
        (N''000002984'', N''18855'', N''Kura'', N''Doustnie w wodzie do picia'', N''Leczenie i metafilaktyka zakażeń przewodu pokarmowego wywołanych przez Escherichia coli wrażliwą na kolistynę.'', N''75 000 j.m. kolistyny/kg m.c./dobę (= 37,5 ml produktu/1000 kg m.c./dobę) przez 3–5 dni.'', N''data/ChPL/RPL/RPL_18855_Colivet_solution_roztwór_doustny_dla_świń_kur_RPL_ChPL.pdf'', N''Świeży roztwór przygotowywać co 24 h.'', N''tk. 1 dzień, Jaja: 0 dni'', N''tk. 1 dzień, Jaja: 0 dni'', N''0 dni''),
        (N''000000000000001553'', N''18855'', N''Kura'', N''Doustnie w wodzie do picia'', N''Leczenie i metafilaktyka zakażeń przewodu pokarmowego wywołanych przez Escherichia coli wrażliwą na kolistynę.'', N''75 000 j.m. kolistyny/kg m.c./dobę (= 37,5 ml produktu/1000 kg m.c./dobę) przez 3–5 dni.'', N''data/ChPL/RPL/RPL_18855_Colivet_solution_roztwór_doustny_dla_świń_kur_RPL_ChPL.pdf'', N''Świeży roztwór przygotowywać co 24 h.'', N''tk. 1 dzień, Jaja: 0 dni'', N''tk. 1 dzień, Jaja: 0 dni'', N''0 dni''),
        (N''000002935'', N''18334'', N''Kura'', N''Do oka, donosowo, w wodzie do picia lub rozpylanie (spray)'', N''Czynne uodparnianie kur przeciwko zakaźnemu zapaleniu oskrzeli ptaków (IB, typ Massachusetts) oraz rzekomemu pomorowi ptaków (ND).'', N''1 dawka/ptaka od 1. dnia życia zgodnie z programem immunoprofilaktyki stada.'', N''data/ChPL/RPL/RPL_18334_Nobilis_MA5_Clone_30_RPL_ChPL.pdf'', N''Stosować czystą wodę wolną od chloru i środków dezynfekcyjnych.'', N''tk. 0 dni, Jaja: 0 dni'', N''tk. 0 dni, Jaja: 0 dni'', N''0 dni''),
        (N''000002962'', N''18357'', N''Kura'', N''Do oka, donosowo, w wodzie do picia lub rozpylanie (spray)'', N''Czynne uodparnianie kur przeciwko rzekomemu pomorowi ptaków (chorobie Newcastle).'', N''1 dawka/ptaka od 1. dnia życia zgodnie z programem szczepień.'', N''data/ChPL/RPL/RPL_18357_Nobilis_ND_Clone_30_RPL_ChPL.pdf'', N''Nie stosować w okresie nieśności bez wskazań ChPL.'', N''tk. 0 dni, Jaja: 0 dni, Nie stosować w okresie nieśności poza zatwierdzonymi wskazaniami.'', N''tk. 0 dni, Jaja: 0 dni, Nie stosować w okresie nieśności poza zatwierdzonymi wskazaniami.'', N''0 dni''),
        (N''03050'', N''100188555'', N''Kura'', N''Doustnie w wodzie do picia'', N''Leczenie i metafilaktyka zakażeń przewodu pokarmowego wywołanych przez Escherichia coli wrażliwą na kolistynę.'', N''75 000 j.m. kolistyny/kg m.c./dobę (= 37,5 ml produktu/1000 kg m.c./dobę) przez 3–5 dni.'', N''data/ChPL/RPL/RPL_18855_Colivet_solution_roztwór_doustny_dla_świń_kur_RPL_ChPL.pdf'', N''Świeży roztwór przygotowywać co 24 h.'', N''tk. 1 dzień, Jaja: 0 dni'', N''tk. 1 dzień, Jaja: 0 dni'', N''0 dni''),
        (N''000003289'', N''100208878'', N''kura'', N''w wodzie do picia'', N''Kokcydioza jelitowa wywołana przez Eimeria spp. wrażliwe na amprolium'', N''20 mg amprolium/kg m.c. na dobę (1 ml/10 kg m.c./dobę) przez 5–7 dni.'', N''data/ChPL/RPL/RPL_20887_Coccibal_RPL_ChPL.pdf'', N''Jaja: 0 dni. Stężenie ustalić na podstawie masy i spożycia wody zgodnie z pkt 3.9.'', N''tk. 0 dni, Jaja: 0 dni. Stężenie ustalić na podstawie masy i spożycia wody zgodnie z pkt 3.9.'', N''tk. 0 dni, Jaja: 0 dni. Stężenie ustalić na podstawie masy i spożycia wody zgodnie z pkt 3.9.'', N''0 dni''),
        (N''000003289'', N''100208878'', N''indyk'', N''w wodzie do picia'', N''Kokcydioza jelitowa wywołana przez Eimeria spp. wrażliwe na amprolium'', N''20 mg amprolium/kg m.c. na dobę (1 ml/10 kg m.c./dobę) przez 5–7 dni.'', N''data/ChPL/RPL/RPL_20887_Coccibal_RPL_ChPL.pdf'', N''Jaja: 0 dni. Stężenie ustalić na podstawie masy i spożycia wody zgodnie z pkt 3.9.'', N''tk. 0 dni, Jaja: 0 dni. Stężenie ustalić na podstawie masy i spożycia wody zgodnie z pkt 3.9.'', N''tk. 0 dni, Jaja: 0 dni. Stężenie ustalić na podstawie masy i spożycia wody zgodnie z pkt 3.9.'', N''0 dni'')
    ) AS entries(symbol,rpl_id,species,route,indication,dose,pdf_path,restrictions,withdrawal_short,price,eggs)
), matched AS (
    SELECT v.id, MIN(c.eggs) AS eggs
    FROM dbo.catalog_variants v
    JOIN dbo.catalog_products p ON p.symbol = v.symbol
    LEFT JOIN dbo.catalog_price_withdrawal w ON w.id = v.id
    JOIN candidates c ON c.symbol = v.symbol AND c.rpl_id = COALESCE(v.rpl_id,N'''')
        AND c.species = v.species AND c.route = COALESCE(v.route,N'''')
        AND c.indication = COALESCE(v.indication,N'''') AND c.dose = COALESCE(v.dose,N'''')
        AND c.pdf_path = v.pdf_path AND c.restrictions = COALESCE(v.restrictions,N'''')
        AND c.withdrawal_short = COALESCE(v.withdrawal_short,N'''')
        AND c.price = COALESCE(w.compact_text,N'''')
    WHERE COALESCE(p.decision,N'''') <> N''NOT_MEDICINE''
    GROUP BY v.id HAVING MIN(c.eggs) = MAX(c.eggs)
)
UPDATE v SET eggs = m.eggs
FROM dbo.catalog_variants v JOIN matched m ON m.id = v.id
WHERE NULLIF(LTRIM(RTRIM(v.eggs)),N'''') IS NULL;

SELECT @@ROWCOUNT AS updated_variants;

-- Candidates for review against ChPL. This query does not set any values.
SELECT v.id, v.symbol, p.name, v.species, v.route, v.restrictions,
       v.withdrawal_short, w.compact_text, v.pdf_path
FROM dbo.catalog_variants v
JOIN dbo.catalog_products p ON p.symbol = v.symbol
LEFT JOIN dbo.catalog_price_withdrawal w ON w.id = v.id
WHERE NULLIF(LTRIM(RTRIM(v.eggs)), N'''') IS NULL
  AND (LOWER(v.species) LIKE N''kur%'' OR LOWER(v.species) LIKE N''%drób%''
    OR LOWER(v.species) LIKE N''indyk%'' OR LOWER(v.species) LIKE N''kaczk%''
    OR LOWER(v.species) LIKE N''gęs%'' OR LOWER(v.species) LIKE N''przepiór%''
    OR LOWER(v.restrictions) LIKE N''%jaj%'' OR LOWER(v.withdrawal_short) LIKE N''%jaj%''
    OR LOWER(w.compact_text) LIKE N''%jaj%'')
ORDER BY p.name, v.id;';
COMMIT TRANSACTION;
